previewCss:
.darma-loader-metronome-tick {
  position: relative;
  width: 46px;
  height: 52px;
}
.darma-loader-metronome-tick::before {
  content: "";
  position: absolute;
  bottom: 2px;
  left: 50%;
  width: 16px;
  height: 6px;
  margin-left: -8px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
}
.darma-loader-metronome-tick i {
  position: absolute;
  bottom: 6px;
  left: 50%;
  width: 4px;
  height: 40px;
  margin-left: -2px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
  transform-origin: bottom center;
  animation: darma-loader-metronome-tick-swing 1.2s ease-in-out infinite;
}
.darma-loader-metronome-tick i::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 50%;
  width: 11px;
  height: 11px;
  margin-left: -5.5px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
}
@keyframes darma-loader-metronome-tick-swing {
  0%, 100% { transform: rotate(-28deg); }
  50% { transform: rotate(28deg); }
}

